"""Rebuild unchanged native Noisesniffer base, full DCT and sparse DCT partitions."""
from pathlib import Path
import argparse,subprocess,json,hashlib
p=argparse.ArgumentParser();p.add_argument('--source-root',required=True);p.add_argument('--build-root',required=True);p.add_argument('--emsdk',required=True);a=p.parse_args()
root=Path(__file__).resolve().parents[1];source=Path(a.source_root).resolve();external=Path(a.build_root).resolve();compiler=Path(a.emsdk)/'upstream/emscripten/em++'
assert '4.0.15' in subprocess.check_output([str(compiler),'--version'],text=True).splitlines()[0]
build=root/'.build';build.mkdir(exist_ok=True);text=(source/'native/contrast.h').read_text();(build/'noisesniffer-sum.h').write_text(text[text.index('template<class'):text.index('static cv::Mat')])
files=[external/'noisesniffer-dct.o',external/'prnu-fma.o',external/'dft-reference.o',external/'cv/lib/libopencv_imgproc.a',external/'cv/lib/libopencv_core.a',external/'cv/3rdparty/lib/libzlib.a']
assert all(f.is_file() for f in files)
exports=['malloc','free','noisesniffer_stream_dct','noisesniffer_stream_sparse_dct','noisesniffer_stream_base','noisesniffer_stream_blocks','noisesniffer_stream_mean8','noisesniffer_stream_optimal','noisesniffer_stream_valid','noisesniffer_stream_means','noisesniffer_stream_variance','noisesniffer_stream_release','cv_noisesniffer_log_tail']
out=root/'vendor/noisesniffer-stream';out.mkdir(parents=True,exist_ok=True)
subprocess.run([str(compiler),str(root/'native/noisesniffer-stream-gpu.cpp'),str(source/'native/noisesniffer-tail.cpp'),*map(str,files),'-I',str(source/'native'),'-I',str(source/'vendor/boost-math/include'),'-I',str(external/'opencv-4.11.0/modules/core/include'),'-I',str(external/'opencv-4.11.0/modules/imgproc/include'),'-I',str(external/'cv'),'-O3','-msimd128','-fexceptions','-ffp-contract=off','-ffile-prefix-map='+str(root)+'/=','-ffile-prefix-map='+str(source)+'/=','-sDISABLE_EXCEPTION_CATCHING=0','-sMODULARIZE=1','-sEXPORT_ES6=1','-sENVIRONMENT=web,worker,node','-sALLOW_MEMORY_GROWTH=1','-sINITIAL_MEMORY=8388608','-sMAXIMUM_MEMORY=134217728','-sMEMORY_GROWTH_LINEAR_STEP=4194304','-sABORTING_MALLOC=0','-sFILESYSTEM=0','-sEXPORTED_FUNCTIONS='+json.dumps(['_'+x for x in exports]),'-sEXPORTED_RUNTIME_METHODS=["HEAPU8","HEAP32","HEAPF32","HEAPF64"]','-o',str(out/'noisesniffer-stream.js')],check=True)
(out/'PINNED-GPU-PARTITION.json').write_text(json.dumps({'schema':1,'method':'unchanged-native-Noisesniffer-base-full-DCT-sparse-DCT-partitions','opencv':'4.11.0','emscripten':'4.0.15','objects':{f.name:hashlib.sha256(f.read_bytes()).hexdigest() for f in files},'outputs':{name:hashlib.sha256((out/name).read_bytes()).hexdigest() for name in ['noisesniffer-stream.js','noisesniffer-stream.wasm']}},indent=2)+'\n')
